const canvas=document.querySelector('#ice-scene'),ctx=canvas.getContext('2d');
const bendButton=document.querySelector('#bend'),autoButton=document.querySelector('#auto'),chargeText=document.querySelector('#charge'),fill=document.querySelector('#fill');
let w=0,h=0,dpr=1,bendTarget=0,bend=0,energy=0,auto=false,time=0,lastBend=0;
const grains=[],brine=[],charges=[],frost=[];
const fluid=new IceFluid(7600),activeTouches={};
function resize(){dpr=Math.min(devicePixelRatio,2);w=innerWidth;h=innerHeight;canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);seed()}
function seed(){grains.length=brine.length=charges.length=frost.length=0;for(let i=0;i<64;i++)grains.push({x:Math.random(),y:Math.random(),r:.035+Math.random()*.075,rot:Math.random()*6.28});for(let i=0;i<420;i++)brine.push({x:Math.random(),y:Math.random(),s:Math.random(),o:.2+Math.random()*.55});for(let i=0;i<6500;i++)frost.push({x:Math.random(),y:Math.random(),z:Math.random(),s:.35+Math.random()*1.3});for(let i=0;i<54;i++)charges.push({p:Math.random(),speed:.12+Math.random()*.16})}
function icePoint(u,v){const width=Math.min(w*.62,900),height=Math.min(h*.3,250),cx=w*.53,cy=h*.59;const s=(u-.5)*2;const arch=-(.30+bend*.58)*height*(1-s*s);const taper=.72+.28*Math.cos(s*Math.PI*.5);const x=cx+(u-.5)*width;const y=cy+arch+(v-.5)*height*taper;return{x,y,width,height}}
function path(){ctx.beginPath();let p=icePoint(0,.04);ctx.moveTo(p.x,p.y);for(let i=0;i<=96;i++){const u=i/96,jag=Math.sin(i*2.17)*.012+Math.sin(i*5.31)*.006;p=icePoint(u,.04+jag);ctx.lineTo(p.x,p.y)}for(let i=96;i>=0;i--){const u=i/96,jag=Math.sin(i*2.73+1.2)*.014;p=icePoint(u,.96+jag);ctx.lineTo(p.x,p.y)}ctx.closePath()}
function lightAt(x,y){const sx=w*.45+Math.sin(time*.19)*w*.085,sy=h*.43+Math.cos(time*.13)*h*.04;const dx=(x-sx)/(w*.16),dy=(y-sy)/(h*.2);return Math.exp(-(dx*dx+dy*dy)*1.72)}
function drawIce(){ctx.save();path();ctx.fillStyle='rgba(7,10,12,.96)';ctx.fill();ctx.clip();
  fluid.draw(ctx,icePoint,lightAt,bend,time);
  ctx.restore();
  path();const c=icePoint(.5,.5),rim=lightAt(c.x,c.y);ctx.strokeStyle=`rgba(137,164,178,${.14+rim*.42})`;ctx.lineWidth=1.15;ctx.shadowColor='rgba(121,187,214,.25)';ctx.shadowBlur=12;ctx.stroke();ctx.shadowBlur=0;
  const left=icePoint(0,.5),right=icePoint(1,.5);ctx.strokeStyle='rgba(148,220,246,.38)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(left.x,left.y);ctx.lineTo(left.x-80,left.y+90);ctx.lineTo(w*.76,h*.83);ctx.lineTo(right.x+64,right.y+60);ctx.lineTo(right.x,right.y);ctx.stroke();
}
function drawCircuit(){const start=icePoint(1,.5),x0=start.x+64,y0=start.y+60,x1=w*.76,y1=h*.83;ctx.save();ctx.strokeStyle='#345866';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(start.x,start.y);ctx.lineTo(x0,y0);ctx.lineTo(x1,y1);ctx.stroke();for(const q of charges){q.p=(q.p+q.speed*Math.abs(bend-lastBend))%1;const x=start.x+(x1-start.x)*q.p,y=start.y+(y1-start.y)*q.p;ctx.fillStyle='white';ctx.shadowColor='#b9efff';ctx.shadowBlur=10;ctx.beginPath();ctx.arc(x,y,1.8,0,6.28);ctx.fill()}ctx.restore();
  ctx.save();ctx.translate(x1,y1);ctx.strokeStyle='#9ee8ff';ctx.lineWidth=2;ctx.strokeRect(-18,-36,36,72);ctx.fillStyle=`rgba(114,220,255,${.12+energy*.006})`;ctx.fillRect(-15,33-energy*.66,30,energy*.66);ctx.fillStyle='#89aebb';ctx.font='9px ui-monospace';ctx.textAlign='center';ctx.fillText('RECTIFIER + C',0,52);ctx.restore()}
function drawForce(){const p=icePoint(.5,0);ctx.strokeStyle=`rgba(255,255,255,${.2+bend*.7})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x,p.y-80);ctx.lineTo(p.x,p.y-18);ctx.stroke();ctx.beginPath();ctx.moveTo(p.x-6,p.y-27);ctx.lineTo(p.x,p.y-18);ctx.lineTo(p.x+6,p.y-27);ctx.stroke();ctx.fillStyle='#89a3ae';ctx.font='9px ui-monospace';ctx.textAlign='center';ctx.fillText('NON-UNIFORM STRAIN',p.x,p.y-91)}
function frame(){time+=.016;if(auto)bendTarget=.48+.42*Math.sin(time*2.1);bend+=(bendTarget-bend)*.075;const delta=Math.abs(bend-lastBend);energy=Math.min(100,energy+delta*12);energy=Math.max(0,energy-.002);ctx.clearRect(0,0,w,h);ctx.fillStyle='#010204';ctx.fillRect(0,0,w,h);const haze=ctx.createRadialGradient(w*.43,h*.42,0,w*.43,h*.42,h*.58);haze.addColorStop(0,'rgba(18,22,26,.16)');haze.addColorStop(.38,'rgba(5,7,9,.05)');haze.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=haze;ctx.fillRect(0,0,w,h);ctx.globalCompositeOperation='screen';drawIce();drawCircuit();drawForce();ctx.globalCompositeOperation='source-over';chargeText.textContent=energy.toFixed(1).padStart(4,'0');fill.style.width=energy+'%';lastBend=bend;requestAnimationFrame(frame)}
function press(on){bendTarget=on?.78:0;bendButton.classList.toggle('active',!!on)}
bendButton.addEventListener('pointerdown',e=>{bendButton.setPointerCapture(e.pointerId);press(true)});bendButton.addEventListener('pointerup',()=>press(false));bendButton.addEventListener('pointercancel',()=>press(false));
autoButton.addEventListener('click',()=>{auto=!auto;autoButton.setAttribute('aria-pressed',String(auto));autoButton.textContent=`循环实验：${auto?'开启':'关闭'}`;if(!auto)press(false)});
canvas.addEventListener('pointermove',e=>{const current=[e.clientX,e.clientY],last=activeTouches[e.pointerId];if(last)fluid.pointerMove(current,last,[w,h]);activeTouches[e.pointerId]=current});
canvas.addEventListener('pointerup',e=>delete activeTouches[e.pointerId]);canvas.addEventListener('pointercancel',e=>delete activeTouches[e.pointerId]);
addEventListener('resize',resize);resize();frame();
